import * as React from "react";

import { useDescendantFlags } from "../lib/descendant-flags";
import { cn } from "../lib/utils";
import { Button } from "./button";
import { Icon, type IconSource } from "./icon";

import helperStyles from "./helpers.module.css";

const alertFlags = {
  "data-has-icon": ":scope > svg",
  "data-has-title": `:scope > :is(.${helperStyles.alertTitle}, .${helperStyles.alertTitleRow})`,
  "data-has-action": ':scope > [data-slot="alert-action"]'
};
const alertWatch = { subtree: false };

function Alert({
  className,
  variant,
  tone = variant === "destructive" ? "bad" : "neutral",
  title,
  badges,
  actions,
  onDismiss,
  band,
  children,
  ref,
  ...props
}: Omit<React.ComponentPropsWithoutRef<"div">, "title"> & {
  variant?: "default" | "destructive" | null;
  tone?: "neutral" | "info" | "ok" | "warn" | "bad";
  /** Without a title the children are the message, still with the tone icon and actions. Children composed from AlertTitle, AlertDescription and an icon render as given. */
  title?: React.ReactNode;
  /** Right after the title: status badges, and a DocumentationLink so it stays paired with the title. They drop below the title before it wraps. Without a title they sit at the end of the message's first line, the place for its DocumentationLink. */
  badges?: React.ReactNode;
  actions?: React.ReactNode;
  onDismiss?: () => void;
  /** A full-width band inside a framed block, such as a notice between a table's toolbar and its header: a rule below it and no side or top edge, at the frame's inline inset. */
  band?: boolean;
} & { ref?: React.Ref<React.ComponentRef<"div">> }) {
  const alertRef = useDescendantFlags(alertFlags, alertWatch, ref);
  const titled = title != null && title !== false;
  const composed = React.Children.toArray(children).some(
    (child) =>
      React.isValidElement(child) &&
      (child.type === AlertTitle ||
        child.type === AlertDescription ||
        child.type === Icon ||
        child.type === "svg")
  );
  return (
    <div
      ref={alertRef}
      data-slot="alert"
      data-variant={variant ?? "default"}
      role={tone === "bad" ? "alert" : "status"}
      data-tone={tone}
      data-band={band || undefined}
      className={cn(helperStyles.alert, "[&>svg]:cipher-lead-line", className)}
      {...props}
    >
      {composed ? (
        children
      ) : (
        <>
          <Icon
            name={
              tone === "bad"
                ? "alert-c"
                : tone === "ok"
                  ? "check-c"
                  : tone === "warn"
                    ? "alert"
                    : "info"
            }
          />
          {titled &&
            (badges ? (
              <div className={cn(helperStyles.alertTitleRow, helperStyles.titleWithBadges)}>
                <AlertTitle>{title}</AlertTitle>
                <span data-slot="alert-badges" className={helperStyles.titleBadges}>
                  {badges}
                </span>
              </div>
            ) : (
              <AlertTitle>{title}</AlertTitle>
            ))}
          <AlertDescription>
            {badges && !titled ? (
              <div className={helperStyles.alertLine}>
                <div>{children}</div>
                <span data-slot="alert-trailing" className={helperStyles.alertTrailing}>
                  {badges}
                </span>
              </div>
            ) : (
              children
            )}
            {actions && <div className={helperStyles.alertActions}>{actions}</div>}
          </AlertDescription>
        </>
      )}
      {onDismiss && (
        <AlertAction>
          <Button
            type="button"
            variant="ghost"
            size="icon-xs"
            aria-label="Dismiss alert"
            onClick={onDismiss}
          >
            <Icon name="x" />
          </Button>
        </AlertAction>
      )}
    </div>
  );
}
Alert.displayName = "Alert";

function AlertTitle({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="alert-title"
      className={cn(
        helperStyles.alertTitle,
        "[&_a:not([data-slot=button])]:underline [&_a:not([data-slot=button])]:underline-offset-3 [&_a:not([data-slot=button])]:hover:text-foreground",
        className
      )}
      {...props}
    />
  );
}
AlertTitle.displayName = "AlertTitle";

function AlertDescription({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="alert-description"
      className={cn(
        helperStyles.alertDescription,
        "text-muted-foreground text-balance md:text-pretty [&_p:not(:last-child)]:mb-4",
        className
      )}
      {...props}
    />
  );
}
AlertDescription.displayName = "AlertDescription";

function AlertAction({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="alert-action"
      className={cn(helperStyles.alertAction, className)}
      {...props}
    />
  );
}
AlertAction.displayName = "AlertAction";

export { Alert, AlertAction, AlertDescription, AlertTitle };

export const Banner = ({
  icon = "lock",
  children,
  action,
  onDismiss,
  className
}: {
  icon?: IconSource;
  children: React.ReactNode;
  action?: React.ReactNode;
  onDismiss?: () => void;
  className?: string;
}) => (
  <div data-slot="banner" role="status" className={cn(helperStyles.banner, className)}>
    <span className={helperStyles.bannerLead}>
      <Icon icon={icon} lead />
      <span className={helperStyles.bannerText}>{children}</span>
    </span>
    {action}
    {onDismiss && (
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        aria-label="Dismiss banner"
        onClick={onDismiss}
      >
        <Icon name="x" />
      </Button>
    )}
  </div>
);

.avatarFallback {
  background: var(--cipher-tint);
  color: var(--cipher-ink);
  font-family: var(--cipher-type-label-font-family);
  font-weight: var(--cipher-type-label-font-weight);
  line-height: 1;
  letter-spacing: 0;
}
.avatarFallback svg {
  width: 50%;
  height: 50%;
  max-width: var(--cipher-size-icon);
  max-height: var(--cipher-size-icon);
}
.count {
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
  font-weight: var(--cipher-type-mono-sm-font-weight);
  letter-spacing: var(--cipher-type-mono-sm-letter-spacing);
  display: inline-flex;
  min-width: var(--cipher-size-count);
  height: var(--cipher-size-count);
  padding: 0 var(--cipher-space-4);
  align-items: center;
  justify-content: center;
  border-radius: 0;
  background: var(--cipher-accent);
  color: var(--cipher-on-accent);
}
.titleCount {
  display: inline-flex;
  align-items: center;
  gap: var(--cipher-space-8);
  max-width: 100%;
}
.titleCount > span:first-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.titleCount > [data-slot="count"] {
  flex: none;
}
.titleCount[data-wrap] {
  display: inline;
}
.titleCount[data-wrap] > span:first-child + * {
  margin-inline-start: var(--cipher-space-8);
  vertical-align: middle;
}
.countInk {
  background: var(--cipher-ink);
  color: var(--cipher-surface);
}
.countNeutral {
  background: var(--cipher-tint);
  color: var(--cipher-text2);
}
.count[data-tone="warn"] {
  background: var(--cipher-warn-bg);
  color: var(--cipher-warn);
}
.count[data-tone="bad"] {
  background: var(--cipher-bad-bg);
  color: var(--cipher-bad);
}
.identity {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.identityText {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.identityTitle {
  font-family: var(--cipher-type-row-title-font-family);
  font-size: var(--cipher-type-row-title-font-size);
  line-height: var(--cipher-type-row-title-line-height);
  font-weight: var(--cipher-type-row-title-font-weight);
  letter-spacing: var(--cipher-type-row-title-letter-spacing);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.identityDescription {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  color: var(--cipher-text2, var(--muted-foreground));
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mono {
  font-family: var(--cipher-font-mono, monospace);
}
.media {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  color: var(--cipher-ink, var(--foreground));
  background: var(--cipher-surface);
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  border-radius: 0;
}
.mediaSmall {
  width: 24px;
  height: 24px;
}
.tile {
  display: flex;
  box-sizing: border-box;
  text-decoration: none;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: var(--cipher-space-12);
  text-align: start;
  border: 1px solid var(--cipher-line-soft, var(--border));
  background: var(--cipher-surface, var(--background));
  color: var(--cipher-ink, var(--foreground));
}
.tile:not([aria-disabled="true"]):hover {
  border-color: var(--cipher-control, var(--border));
  background: var(--cipher-hover);
}
.tile[data-in-frame] {
  border-color: transparent;
  background: var(--cipher-tint);
}
.tile[data-in-frame]:not([aria-disabled="true"]):hover {
  background: color-mix(in srgb, var(--cipher-mix-ink) var(--cipher-hover-mix), var(--cipher-tint));
}
.tile[aria-pressed="true"],
.tile[aria-current="page"] {
  border-color: var(--cipher-ink, var(--foreground));
}
.tile:disabled,
.tile[data-disabled] {
  cursor: not-allowed;
  opacity: 0.5;
}
.tile:focus-visible {
  outline: 2px solid var(--ring, var(--ring));
  outline-offset: 2px;
}
.tileBody {
  flex: 1;
  min-width: 0;
}
.tile:not([data-layout="stacked"]) {
  flex-wrap: wrap;
  align-content: flex-start;
  align-items: flex-start;
}
.tile:not([data-layout="stacked"]) > .tileBody,
.tile:not([data-layout="stacked"]) > svg:last-child {
  align-self: center;
}
.tile[aria-disabled="true"] {
  cursor: not-allowed;
}
.tile[data-layout="stacked"] {
  flex-direction: column;
  align-items: stretch;
  gap: var(--cipher-space-4);
  padding: var(--cipher-space-16);
}
.tile[data-layout="stacked"] > .tileBody {
  flex: 1 1 auto;
}
.tileTop {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--cipher-space-12);
  min-width: 0;
  margin-bottom: var(--cipher-space-8);
}
.tileAside {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  min-width: 0;
  margin-inline-start: auto;
  color: var(--cipher-muted);
}
.tileAside > :not(.tileEyebrow) {
  flex: none;
}
.tileEyebrow {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--cipher-muted);
  font-family: var(--cipher-type-eyebrow-font-family);
  font-size: var(--cipher-type-eyebrow-font-size);
  line-height: var(--cipher-type-eyebrow-line-height);
  font-weight: var(--cipher-type-eyebrow-font-weight);
  letter-spacing: var(--cipher-type-eyebrow-letter-spacing);
  text-transform: uppercase;
}
.tile[aria-disabled="true"]:not([data-disabled]) > .tileTop {
  opacity: 0.5;
}
.banner {
  display: flex;
  width: 100%;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  border: 1px solid var(--cipher-accent-line);
  background: var(--cipher-accent-wash);
  color: var(--cipher-ink, var(--foreground));
  padding: 10px 16px;
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.bannerLead {
  display: flex;
  flex: 1;
  align-items: flex-start;
  gap: 12px;
  min-width: min(100%, 160px);
}
.bannerLead > svg {
  --cipher-lead-size: var(--cipher-size-icon-small);
  width: var(--cipher-size-icon-small);
  height: var(--cipher-size-icon-small);
  color: var(--cipher-accent-fg);
}
.bannerText {
  flex: 1;
  min-width: 0;
}
.steps {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 0;
  margin: 0;
  list-style: none;
}
.step {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-weight: var(--cipher-type-caption-font-weight);
  letter-spacing: var(--cipher-type-caption-letter-spacing);
  color: var(--cipher-muted, var(--muted-foreground));
}
.step[data-current] {
  color: var(--cipher-ink, var(--foreground));
  font-weight: var(--cipher-type-title-sm-font-weight);
}
.stepNumber {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border: 1px solid var(--cipher-line-soft, var(--border));
}
.step[data-current] .stepNumber {
  background: repeating-linear-gradient(
    135deg,
    var(--cipher-tint, var(--muted)) 0 2px,
    transparent 2px 4px
  );
  border-color: var(--cipher-ink, var(--foreground));
}
:global(.cipher) {
  --cipher-toast-bottom: var(--cipher-space-action-bar-offset);
}
:global(.cipher)[data-action-bar-reserve] {
  --cipher-toast-bottom: calc(
    var(--cipher-size-action-bar) + 2 * var(--cipher-space-action-bar-offset)
  );
}
.toastFixed {
  position: fixed;
  inset-inline-end: var(--cipher-space-16);
  bottom: var(--cipher-toast-bottom);
  z-index: 100;
  transition: bottom var(--cipher-duration-moderate) var(--cipher-ease-standard);
}
@media (prefers-reduced-motion: reduce) {
  .toastFixed {
    transition-duration: 0s;
  }
}
.toastTitle {
  font-family: var(--cipher-type-row-title-font-family);
  font-size: var(--cipher-type-row-title-font-size);
  line-height: var(--cipher-type-row-title-line-height);
  font-weight: var(--cipher-type-row-title-font-weight);
  letter-spacing: var(--cipher-type-row-title-letter-spacing);
}
.toastDescription {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  margin-top: 2px;
  color: var(--cipher-text2, var(--muted-foreground));
}
.avatarStatus[data-status="ok"] {
  background: var(--cipher-ok);
}
.avatarStatus[data-status="warn"] {
  background: var(--cipher-warn);
}
.fieldLabels {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-field-label);
  min-width: 0;
}
.fieldLabelRow {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-4);
  min-width: 0;
}
.globHelp {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-4);
}
.legendRow {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-4);
  width: 100%;
  min-width: 0;
  padding: 0;
}
.legendActions {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  margin-inline-start: auto;
}
.fieldHelp {
  margin-block: calc(
    (var(--cipher-type-field-label-line-height) - var(--cipher-size-control-xs)) / 2
  );
  color: var(--cipher-muted);
}
.fieldDescription {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  margin: 0;
  color: var(--cipher-muted, var(--muted-foreground));
}
.fieldError {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  display: flex;
  align-items: flex-start;
  gap: var(--cipher-space-6);
  margin: 0;
  color: var(--cipher-bad);
  --cipher-lead-line: var(--cipher-type-small-line-height);
}
.fieldErrorLines {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-2);
}
.field[data-note-row] {
  flex-wrap: wrap;
}
.field[data-note-row] > :is(.fieldError, .fieldDescription) {
  flex-basis: 100%;
}
.fieldControl {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-field-label);
  flex: 1;
  min-width: 0;
}
.badge {
  --cipher-badge-glyph: var(--cipher-size-badge-glyph);
  --cipher-badge-media: var(--cipher-size-icon-sm);
  --cipher-lead-line: calc(var(--cipher-badge-height) - 2 * var(--cipher-size-control-border));
  --cipher-lead-size: var(--cipher-badge-glyph);
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-weight: var(--cipher-type-caption-font-weight);
  letter-spacing: var(--cipher-type-caption-letter-spacing);
  --cipher-badge-pad: var(--cipher-space-8);
  box-sizing: border-box;
  max-width: 100%;
  --cipher-badge-height: var(--cipher-size-badge);
  height: var(--cipher-badge-height);
  padding: 0 var(--cipher-badge-pad);
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  border-radius: 0;
}
.badge[data-collapse] {
  flex-shrink: 1000;
  justify-content: flex-start;
  min-width: calc(
    min(6ch, 100%) + 2 * var(--cipher-badge-pad) + 2 * var(--cipher-size-control-border)
  );
}
.badge[data-collapse][data-fit] {
  flex-shrink: 0;
  min-width: auto;
}
.badge > :is(svg, .badgeDot) {
  flex: none;
}
.badge[data-collapse]:has(> svg, > .badgeDot, > .badgeMedia) {
  min-width: calc(
    var(--cipher-badge-glyph) + 2 * var(--cipher-badge-pad) + 2 * var(--cipher-size-control-border)
  );
}
.badge[data-collapse]:has(> .badgeMedia) {
  min-width: calc(
    var(--cipher-badge-media) + 2 * var(--cipher-badge-pad) + 2 * var(--cipher-size-control-border)
  );
}
.badge[data-collapse]:has(> .badgeDot):not(:has(> svg, > .badgeMedia)) {
  min-width: calc(6px + 2 * var(--cipher-badge-pad) + 2 * var(--cipher-size-control-border));
}
.badgeMedia {
  --cipher-lead-size: var(--cipher-badge-media);
  display: inline-flex;
  flex: none;
  width: var(--cipher-badge-media);
  height: var(--cipher-badge-media);
  overflow: hidden;
}
.badge:not([data-size^="control"]) > .badgeMedia {
  margin-inline-end: calc(var(--cipher-space-6) - var(--cipher-space-4));
}
.badgeMedia > :is(img, svg) {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.badgeText {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.badgeText svg {
  display: inline-block;
  width: var(--cipher-badge-glyph);
  height: var(--cipher-badge-glyph);
  vertical-align: middle;
}
.badgeGroup {
  position: relative;
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: var(--cipher-space-4);
  min-width: 0;
}
.badgeGroup > [data-slot="badge"]:first-child {
  flex-shrink: 1;
  min-width: 0;
}
.badgeGroupMeasure {
  position: absolute;
  inset: 0 0 auto;
  display: flex;
  flex-wrap: nowrap;
  gap: inherit;
  height: 0;
  overflow: hidden;
  visibility: hidden;
}
.badgeGroupMore {
  display: flex;
  flex-wrap: wrap;
  gap: var(--cipher-space-4);
}
.badgeGroup[data-wrap] {
  flex-wrap: wrap;
}
:is(.badgeGroupMore, .badgeGroup[data-wrap]) > [data-slot="badge"] {
  align-items: flex-start;
  max-width: 100%;
  height: auto;
  min-height: var(--cipher-badge-height);
  white-space: normal;
  text-align: start;
}
:is(.badgeGroupMore, .badgeGroup[data-wrap]) .badgeText {
  align-self: center;
  overflow-wrap: anywhere;
}
.badge.mono {
  font-family: var(--cipher-type-mono-sm-font-family);
}
.badge[data-slot][data-tone] {
  border-color: transparent;
  color: var(--cipher-muted);
  background: transparent;
}
.badge[data-slot][data-tone="outline"] {
  border-color: var(--cipher-line-soft);
}
.badge[data-size="sm"] {
  --cipher-badge-glyph: var(--cipher-size-badge-glyph-sm);
  --cipher-badge-media: var(--cipher-badge-glyph);
  --cipher-badge-pad: var(--cipher-space-6);
  --cipher-badge-height: var(--cipher-size-badge-sm);
  height: var(--cipher-badge-height);
  line-height: calc(var(--cipher-size-badge-sm) - 2 * var(--cipher-size-control-border));
}
.badge:is([data-size="control-sm"], [data-size="control-md"], [data-size="control-lg"]) {
  --cipher-badge-glyph: var(--cipher-size-icon);
  --cipher-badge-media: var(--cipher-badge-glyph);
  gap: var(--cipher-space-control-gap);
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
}
.badge[data-size="control-sm"] {
  --cipher-badge-glyph: var(--cipher-size-icon-label);
  --cipher-badge-pad: var(--cipher-space-control-inline-sm);
  --cipher-badge-height: var(--cipher-size-control-sm);
  height: var(--cipher-badge-height);
}
.badge[data-size="control-md"] {
  --cipher-badge-pad: var(--cipher-space-control-inline-md);
  --cipher-badge-height: var(--cipher-size-control-md);
  height: var(--cipher-badge-height);
}
.badge[data-size="control-lg"] {
  --cipher-badge-pad: var(--cipher-space-control-inline);
  --cipher-badge-height: var(--cipher-size-control-lg);
  height: var(--cipher-badge-height);
}
.badge[data-slot][data-tone="soft"] {
  background: var(--cipher-badge-soft);
  color: var(--cipher-text2);
}
.badge[data-slot][data-tone="solid"] {
  background: var(--cipher-ink);
  color: var(--cipher-on-ink);
}
.badge[data-slot][data-tone="accent"] {
  background: var(--cipher-accent);
  color: var(--cipher-on-accent);
}
.badge[data-slot][data-tone="ok"] {
  background: var(--cipher-ok-bg);
  color: var(--cipher-ok);
}
.badge[data-slot][data-tone="warn"] {
  background: var(--cipher-warn-bg);
  color: var(--cipher-warn);
}
.badge[data-slot][data-tone="bad"] {
  background: var(--cipher-bad-bg);
  color: var(--cipher-bad);
}
.badge[data-slot][data-tone="info"] {
  background: var(--cipher-info-bg);
  color: var(--cipher-info);
}
.badgeDot {
  --cipher-lead-size: 6px;
  width: 6px;
  height: 6px;
  background: currentColor;
  flex-shrink: 0;
}
.steps .step {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
}
.steps .step::before {
  content: "";
  display: block;
  width: 100%;
  height: 6px;
  background: var(--cipher-line-soft);
}
.steps .step[data-complete]::before {
  background: var(--cipher-ink);
}
.steps .step[data-current]::before {
  background: repeating-linear-gradient(
    135deg,
    var(--cipher-ink) 0 2px,
    var(--cipher-line-soft) 2px 4px
  );
}
.fieldset {
  min-width: 0;
  width: 100%;
  padding: 0;
  border: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.fieldset > legend {
  font-family: var(--cipher-type-field-label-font-family);
  font-size: var(--cipher-type-field-label-font-size);
  line-height: var(--cipher-type-field-label-line-height);
  font-weight: var(--cipher-type-field-label-font-weight);
  letter-spacing: var(--cipher-type-field-label-letter-spacing);
  margin-bottom: 6px;
}
.alert[data-tone="neutral"] {
  background: var(--cipher-paper);
  border-color: var(--cipher-line-soft);
  color: var(--cipher-ink);
}
.alert[data-tone="neutral"] > svg {
  color: var(--cipher-muted);
}
.alert[data-tone="info"] {
  background: var(--cipher-info-bg);
  border-color: var(--cipher-info-line);
  color: var(--cipher-info);
}
.alert[data-tone="ok"] {
  background: var(--cipher-ok-bg);
  border-color: var(--cipher-ok-line);
  color: var(--cipher-ok);
}
.alert[data-tone="warn"] {
  background: var(--cipher-warn-bg);
  border-color: var(--cipher-warn-line);
  color: var(--cipher-warn);
}
.alert[data-tone="bad"] {
  background: var(--cipher-bad-bg);
  border-color: var(--cipher-bad-line);
  color: var(--cipher-bad);
}
.alertActions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--cipher-space-8);
  padding-top: var(--cipher-space-actions-gap);
}
.toastStack {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-8);
  width: max-content;
  max-width: min(var(--cipher-size-toast), 100%);
}
.toastStack.toastFixed {
  max-width: min(var(--cipher-size-toast), calc(100vw - 2 * var(--cipher-space-16)));
}
.toast {
  border-radius: 0;
  display: flex;
  align-items: flex-start;
  gap: var(--cipher-space-8);
  border: 1px solid var(--cipher-line-soft, var(--border));
  background: var(--cipher-toast-bg, var(--popover));
  color: var(--cipher-ink, var(--foreground));
  box-shadow: var(--cipher-shadow-pop, 0 4px 16px rgb(0 0 0 / 0.12));
  padding: var(--cipher-space-12);
  --cipher-toast-line: var(--cipher-type-row-title-line-height);
}
.toast > svg {
  flex: none;
  height: var(--cipher-toast-line);
}
.toastBody {
  min-width: 0;
  flex: 1 1 auto;
}
.toastTitle,
.toastDescription {
  overflow-wrap: anywhere;
}
.toast > button {
  flex: none;
  margin-block: calc((var(--cipher-toast-line) - var(--cipher-action-height)) / 2);
}
.toastActions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--cipher-space-4);
  margin-top: var(--cipher-space-8);
  margin-inline-start: calc(-1 * var(--cipher-space-control-inline-sm));
  contain: inline-size;
}
.toastActions > button {
  white-space: normal;
  max-width: 100%;
}
.avatarShape {
  border-radius: 0;
}
.avatarShape::after {
  content: "";
  position: absolute;
  inset: 0;
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  mix-blend-mode: var(--cipher-avatar-blend);
  pointer-events: none;
}
.avatarShape::after,
.avatarShape > [data-slot="avatar-fallback"],
.avatarShape > [data-slot="avatar-image"] {
  border-radius: inherit;
}
.avatarShape > [data-slot="avatar-fallback"] {
  font-size: inherit;
}
.avatarRing {
  box-shadow: 0 0 0 var(--cipher-size-focus-ring) var(--cipher-surface);
}
.avatarGroup {
  display: flex;
}
.avatarGroup > [data-slot="avatar"] + [data-slot="avatar"],
.avatarGroup > * + [data-slot="avatar-group-count"] {
  margin-inline-start: calc(-1 * var(--cipher-space-4));
}
.avatarCount {
  border-radius: 0;
  background: var(--cipher-tint);
  color: var(--cipher-muted);
  box-shadow: 0 0 0 var(--cipher-size-focus-ring) var(--cipher-surface);
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  font-weight: var(--cipher-type-caption-font-weight);
}
.avatarStatus {
  position: absolute;
  z-index: 1;
  inset-inline-end: calc(-1 * var(--cipher-space-2));
  bottom: calc(-1 * var(--cipher-space-2));
  width: var(--cipher-space-8);
  height: var(--cipher-space-8);
  box-shadow: 0 0 0 var(--cipher-size-focus-ring) var(--cipher-surface);
  background: var(--cipher-faint);
  border-radius: 0;
}

.fieldLegend {
  font-family: var(--cipher-type-title-sm-font-family);
  font-size: var(--cipher-type-title-sm-font-size);
  line-height: var(--cipher-type-title-sm-line-height);
  font-weight: var(--cipher-type-title-sm-font-weight);
  letter-spacing: var(--cipher-type-title-sm-letter-spacing);
  margin-bottom: var(--cipher-space-field-label);
}
.fieldLegend[data-variant="legend"] {
  margin-bottom: var(--cipher-space-field-legend);
}
.fieldLegend[data-variant="legend"] + .fieldDescription {
  margin-top: calc(var(--cipher-space-field-label) - var(--cipher-space-field-legend));
}
[data-slot="field-set"]:has(> .fieldLegend[data-variant="legend"]) {
  row-gap: var(--cipher-space-field-legend);
}
.fieldGroup > [data-slot="field-set"]:has(> .fieldLegend[data-variant="legend"]) + *,
.fieldGroup > * + [data-slot="field-set"]:has(> .fieldLegend[data-variant="legend"]) {
  margin-top: calc(var(--cipher-space-content-section) - var(--cipher-space-field-group));
}
.fieldLegend[data-variant="label"] {
  font-family: var(--cipher-type-field-label-font-family);
  font-size: var(--cipher-type-field-label-font-size);
  line-height: var(--cipher-type-field-label-line-height);
  font-weight: var(--cipher-type-field-label-font-weight);
  letter-spacing: var(--cipher-type-field-label-letter-spacing);
}
.alertTitle {
  grid-column: 1;
  grid-row: 1;
  min-width: 0;
  font-family: var(--cipher-type-row-title-font-family);
  font-size: var(--cipher-type-row-title-font-size);
  line-height: var(--cipher-type-row-title-line-height);
  font-weight: var(--cipher-type-row-title-font-weight);
  letter-spacing: var(--cipher-type-row-title-letter-spacing);
}
.alertDescription {
  grid-column: 1;
  min-width: 0;
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}

:is(.fieldDescription, .alertDescription) a:not([data-slot]) {
  color: var(--cipher-link);
  text-decoration-line: none;
  text-decoration-thickness: var(--cipher-size-control-border);
  text-underline-offset: var(--cipher-space-3);
}
:is(.fieldDescription, .alertDescription) a:not([data-slot]):focus-visible {
  text-decoration-line: underline;
}
@media (hover: hover) {
  :is(.fieldDescription, .alertDescription) a:not([data-slot]):hover {
    color: var(--cipher-text2);
    text-decoration-line: underline;
    text-decoration-thickness: var(--cipher-space-2);
  }
}

.alert {
  position: relative;
  display: grid;
  width: 100%;
  grid-template-columns: minmax(0, 1fr);
  border: 1px solid var(--cipher-line-soft);
  border-radius: 0;
  padding: var(--cipher-space-12);
  gap: var(--cipher-space-4) var(--cipher-space-8);
  overflow-wrap: anywhere;
  text-align: start;
}
.alert[data-has-icon] {
  grid-template-columns: auto minmax(0, 1fr);
}
.alert[data-band] {
  border-width: 0 0 var(--cipher-size-control-border);
  padding: var(--cipher-space-4) var(--cipher-space-surface-inset-sm);
}
.alert > svg {
  --cipher-lead-line: var(--cipher-type-row-title-line-height);
  grid-column: 1;
  grid-row: 1;
  color: currentColor;
}
.alert[data-has-icon]:not([data-has-title]) > svg {
  --cipher-lead-line: var(--cipher-type-small-line-height);
  --cipher-lead-size: var(--cipher-size-icon-small);
  grid-row: 1;
  width: var(--cipher-size-icon-small);
  height: var(--cipher-size-icon-small);
}
.alert[data-has-icon] > :is(.alertTitle, .alertDescription) {
  grid-column: 2;
}
.alert[data-has-title] > .alertDescription {
  grid-row: 2;
}
.alert[data-has-action] {
  grid-template-columns: minmax(0, 1fr) auto;
  padding-inline-end: var(--cipher-space-12);
}
.alert[data-has-icon][data-has-action] {
  grid-template-columns: auto minmax(0, 1fr) auto;
}
.alert[data-has-icon] > .alertTitleRow {
  grid-column: 2;
}
.alertTitleRow {
  grid-row: 1;
  --cipher-title-badges-line: var(--cipher-type-row-title-line-height);
}
.alertLine {
  display: flex;
  align-items: flex-start;
  gap: var(--cipher-space-8);
}
.alertLine > :first-child {
  flex: 1;
  min-width: 0;
}
.alertTrailing {
  display: inline-flex;
  flex: 0 1 auto;
  flex-wrap: wrap;
  justify-content: flex-end;
  max-width: 50%;
  align-items: center;
  gap: var(--cipher-space-6);
  min-height: var(--cipher-type-small-line-height);
}
.titleWithBadges {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--cipher-space-4) var(--cipher-space-8);
  min-width: 0;
}
.titleWithBadges > :first-child {
  flex: 0 1 auto;
  min-width: 0;
}
.titleBadges {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--cipher-space-6);
  min-width: 0;
  max-width: 100%;
  min-height: var(--cipher-title-badges-line, auto);
}
:is(.titleBadges, .alertTrailing) > :not([data-slot="documentation-link"]) {
  max-width: 100%;
}
.alertAction {
  position: static;
  grid-column: -2 / -1;
  grid-row: 1;
  align-self: start;
}
.alert[data-has-title]:has(> .alertDescription) > :is(svg, .alertAction) {
  grid-row: 1 / span 2;
}

.fieldTitle {
  font-family: var(--cipher-type-field-label-font-family);
  font-size: var(--cipher-type-field-label-font-size);
  line-height: var(--cipher-type-field-label-line-height);
  font-weight: var(--cipher-type-field-label-font-weight);
  letter-spacing: var(--cipher-type-field-label-letter-spacing);
}
.fieldGroup {
  gap: var(--cipher-space-field-group);
}
.field {
  gap: var(--cipher-space-field-label);
}
.field:not([data-orientation="horizontal"]),
.field[data-orientation="horizontal"]:not([data-width="wide"]):is(
    :global([data-slot="field"]:not([data-orientation="horizontal"])) ~ *,
    :has(~ :global([data-slot="field"]:not([data-orientation="horizontal"])))
  ) {
  max-width: var(--cipher-size-measure-field);
}
.field[data-width="wide"] {
  max-width: var(--cipher-size-measure-field-wide);
}
.field[data-orientation="horizontal"] {
  gap: var(--cipher-space-12);
}
